// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(c.balanceOf(address(this)) >= _value);
        uint256 supplyBefore = c.totalSupply();
        c.burn(_value);
        assertTrue(c.totalSupply() == supplyBefore - _value);
    }
}

